import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"CSV Export","description":"Download the data of a view as a CSV file.","frontmatter":{"title":"CSV Export","description":"Download the data of a view as a CSV file."},"headers":[],"relativePath":"en/grids/csv-export.md","filePath":"en/grids/csv-export.md","lastUpdated":1787319236000}'),s={name:"en/grids/csv-export.md"};function i(n,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="csv-export" tabindex="-1">CSV Export <a class="header-anchor" href="#csv-export" aria-label="Permalink to &quot;CSV Export&quot;">​</a></h1><p>Via <strong>More</strong> (⋮) → <strong>Export as CSV</strong>, you download a view&#39;s data as a spreadsheet file.</p><h2 id="what-gets-exported" tabindex="-1">What gets exported <a class="header-anchor" href="#what-gets-exported" aria-label="Permalink to &quot;What gets exported&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">The export follows the view, not the Grid</p><p>Exactly what&#39;s visible in the current <strong>view</strong> gets exported:</p><ul><li>only the entries the <strong>filter</strong> lets through</li><li>only the <strong>visible</strong> columns</li><li>in the current column order and sort order</li></ul><p>If you want everything, switch to an unfiltered view with all columns first.</p></div><div class="tip custom-block"><p class="custom-block-title">A view specifically for exporting</p><p>If you export regularly, a dedicated view pays off: exactly the columns you need, in the order the target system expects, with the right filter. Then the export is one click instead of rebuilding it every time.</p></div><h2 id="what-the-export-is-useful-for" tabindex="-1">What the export is useful for <a class="header-anchor" href="#what-the-export-is-useful-for" aria-label="Permalink to &quot;What the export is useful for&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Purpose</th><th>Note</th></tr></thead><tbody><tr><td><strong>Backup before risky changes</strong></td><td>Before type changes and bulk deletions</td></tr><tr><td><strong>Analysis in a spreadsheet application</strong></td><td>For calculations ApptiveGrid doesn&#39;t cover</td></tr><tr><td><strong>Handover to another system</strong></td><td>Accounting, mail merge, statistics</td></tr><tr><td><strong>Moving to another Grid</strong></td><td>Export, then <a href="/en/grids/csv-import">CSV import</a></td></tr></tbody></table><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">What the export doesn&#39;t take along</p><ul><li><strong>File attachments</strong> — only references or names, not the files themselves</li><li><strong>Links</strong> — as display text, not as a reference. Re-importing doesn&#39;t recreate a link.</li><li><strong>Calculated fields</strong> — as the calculated value, not as the calculation rule</li><li><strong>Hidden columns</strong> — not at all</li><li><strong>Structure</strong> — views, forms, flows, and pages can&#39;t be exported</li></ul></div><p>For a complete migration, a CSV export is therefore <strong>not a backup of the structure</strong>. It backs up the data, not the application.</p><h2 id="accented-characters-and-excel" tabindex="-1">Accented characters and Excel <a class="header-anchor" href="#accented-characters-and-excel" aria-label="Permalink to &quot;Accented characters and Excel&quot;">​</a></h2><p>The exported file is UTF-8 encoded.</p><div class="tip custom-block"><p class="custom-block-title">When Excel breaks accented characters</p><p>Double-clicking the CSV file opens it with the wrong encoding in some Excel versions — <code>Müller</code> becomes <code>MÃ¼ller</code>.</p><p>The reliable route: in Excel, use <em>Data → From Text/CSV</em>, and choose <strong>UTF-8</strong> as the file origin there. In LibreOffice Calc, the import dialog appears automatically.</p><p>The export itself is fine — it&#39;s an opening problem.</p></div><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p>The export requires the appropriate rights. If the menu item is missing, check your <a href="/en/zusammenarbeit/rollen">role</a>.</p><p>In published <a href="/en/seiten/portal-veroeffentlichen">portals</a>, you control whether visitors can export via the block setting <strong>Show CSV download</strong>.</p><div class="warning custom-block"><p class="custom-block-title">Enable export in portals deliberately</p><p>If <em>Show CSV download</em> is on, visitors can download the entire visible dataset — not just view it. For portals with personal data, you should leave this off.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/grids/csv-import">CSV Import</a></li><li><a href="/en/ansichten/spalten-verwalten">Manage columns</a></li><li><a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></li></ul>',19)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
